sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.ch-hero {
  position: relative;
  width: 100%;
  min-height: 600px;
  display: flex;
  align-items: center;
  box-sizing: border-box;
  background:
    linear-gradient(90deg, rgba(250, 246, 239, .92) 0%, rgba(250, 246, 239, .55) 45%, rgba(250, 246, 239, 0) 70%),
    url('/x_2206701_hotel_0.hotel-hero.jpg') center / cover no-repeat,
    #e8eee9;
  font-family: 'Inter', system-ui, -apple-system, 'Segoe UI', Arial, sans-serif;
  font-size: 15px;
  line-height: 1.6;
}
.ch-hero *, .ch-hero *::before, .ch-hero *::after { box-sizing: border-box; }

.ch-hero-container { width: 92%; max-width: 1120px; margin: 0 auto; }

/* bottom padding leaves room for the search bar to overlap (next feature) */
.ch-hero-inner { padding: 70px 0 130px; max-width: 520px; }

.ch-hero-eyebrow {
  display: block;
  margin-bottom: 10px;
  font-size: .72rem;
  font-weight: 500;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: #6f756f;
}

.ch-hero h1 {
  margin: 0;
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: 4rem;
  font-weight: 600;
  line-height: 1.15;
  color: #1f3a30;
}

@media (max-width: 1279px) { .ch-hero h1 { font-size: 5vw; } }
@media (max-width: 832px)  { .ch-hero h1 { font-size: 2.6rem; } }

.ch-hero h1 .ch-hero-script {
  display: block;
  margin-top: 4px;
  font-family: 'Allura', cursive;
  font-size: 1.15em;
  font-weight: 400;
  color: #1f3a30;
}

.ch-hero p {
  max-width: 440px;
  margin: 20px 0 28px;
  color: #444a44;
  font-size: 15px;
  line-height: 1.6;
}

.ch-hero-actions { display: flex; flex-wrap: wrap; gap: 12px; }

.ch-hero a.ch-hero-btn {
  display: inline-block;
  padding: 12px 26px;
  border: 1px solid transparent;
  border-radius: 6px;
  font-family: inherit;
  font-size: .78rem;
  font-weight: 600;
  letter-spacing: .12em;
  text-transform: uppercase;
  text-decoration: none;
  cursor: pointer;
  transition: .25s ease;
}

.ch-hero a.ch-hero-btn-green { background: #1f3a30; color: #ffffff; }
.ch-hero a.ch-hero-btn-green:hover {
  background: #162a22;
  color: #ffffff;
  transform: translateY(-2px);
  box-shadow: 0 10px 30px rgba(31, 58, 48, .08);
}

.ch-hero a.ch-hero-btn-outline { background: transparent; border-color: #1f3a30; color: #1f3a30; }
.ch-hero a.ch-hero-btn-outline:hover { background: #1f3a30; color: #ffffff; }

@media (max-width: 900px) {
  .ch-hero-inner { padding-bottom: 150px; }
}
